#include <WiFi.h>
#include <WebServer.h>

// Пины по схеме
#define PIN_LEAK D10 // SENS1.SENSE - датчик протечки (высокий при воде)
#define PIN_BUTTON D1 // SW1 - кнопка тест/сброс
#define PIN_LED D2 // LED1
#define PIN_BUZZER D3 // Q1 base -> buzzer

const char* WIFI_SSID = "YOUR_SSID";
const char* WIFI_PASS = "YOUR_PASSWORD";

WebServer server(80);

bool leakDetected = false;
bool muted = false;
unsigned long muteUntil = 0;
unsigned long lastCheck = 0;

void handleRoot() {
  String html = "<!DOCTYPE html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>";
  html += "<title>Датчик протечки</title></head><body style='font-family:sans-serif;text-align:center;padding:20px'>";
  html += "<h1>Датчик протечки воды</h1>";
  if (leakDetected) html += "<h2 style='color:red'>⚠️ ПРОТЕЧКА ОБНАРУЖЕНА!</h2>";
  else html += "<h2 style='color:green'>Сухо - все в порядке</h2>";
  if (muted) html += "<p>Звук приглушен на 5 мин</p>";
  html += "<p><a href='/mute'><button style='padding:12px 24px'>Приглушить</button></a> ""<a href='/test'><button style='padding:12px 24px'>Тест сирены</button></a></p>";
  html += "<p>Обновление каждые 3с</p><script>setTimeout(()=>location.reload(),3000)</script></body></html>";
  server.send(200, "text/html; charset=utf-8", html);
}
void handleMute(){ muted=true; muteUntil=millis()+5*60*1000; server.sendHeader("Location","/"); server.send(303);}
void handleTest(){ digitalWrite(PIN_LED,HIGH); digitalWrite(PIN_BUZZER,HIGH); delay(500); digitalWrite(PIN_BUZZER,LOW); digitalWrite(PIN_LED,LOW); server.sendHeader("Location","/"); server.send(303);}

void setup() {
  pinMode(PIN_LEAK, INPUT); // зонд замыкает на GND при воде? инверсия обработана
  pinMode(PIN_BUTTON, INPUT_PULLUP);
  pinMode(PIN_LED, OUTPUT);
  pinMode(PIN_BUZZER, OUTPUT);
  digitalWrite(PIN_LED, LOW);
  digitalWrite(PIN_BUZZER, LOW);
  Serial.begin(115200);

  // WiFi - не блокируем работу без него
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  unsigned long t0=millis();
  while (WiFi.status()!=WL_CONNECTED && millis()-t0<8000) delay(200);

  server.on("/", handleRoot);
  server.on("/mute", handleMute);
  server.on("/test", handleTest);
  server.begin();
  // Короткий сигнал включения
  digitalWrite(PIN_BUZZER,HIGH); delay(100); digitalWrite(PIN_BUZZER,LOW);
}

void loop() {
  server.handleClient();
  // Кнопка - сброс/мьют с дебаунсом
  static unsigned long lastBtn=0;
  if (digitalRead(PIN_BUTTON)==LOW && millis()-lastBtn>500) {
    lastBtn=millis();
    if (leakDetected) { muted=true; muteUntil=millis()+5*60000; }
    else { // тест
      digitalWrite(PIN_BUZZER,HIGH); digitalWrite(PIN_LED,HIGH); delay(300); digitalWrite(PIN_BUZZER,LOW); digitalWrite(PIN_LED,LOW);
    }
  }
  if (muted && millis()>muteUntil) muted=false;

  // Опрос датчика каждые 200мс
  if (millis()-lastCheck>200) {
    lastCheck=millis();
    int v=digitalRead(PIN_LEAK);
    // leak_probe: SENSE замыкается на GND при воде -> LOW = протечка
    leakDetected = (v==LOW);
  }

  // Сигнализация
  if (leakDetected && !muted) {
    // прерывистая сирена 1кГц через транзистор - вкл/выкл 400мс
    bool on = (millis()%800)<400;
    digitalWrite(PIN_BUZZER, on? HIGH:LOW);
    digitalWrite(PIN_LED, on? HIGH:LOW);
  } else if (!leakDetected) {
    digitalWrite(PIN_BUZZER, LOW);
    // медленное мигание раз в 3с - жив
    digitalWrite(PIN_LED, (millis()%3000)<100 ? HIGH:LOW);
  } else {
    digitalWrite(PIN_BUZZER, LOW);
    digitalWrite(PIN_LED, HIGH); // горит но без звука
  }

  // Глубокий сон если на батарее и сухо - просыпаемся каждые 10с или по кнопке D1 (GPIO3 wake)
  // esp_sleep_enable_timer_wakeup(10*1000000);
  // esp_sleep_enable_ext0_wakeup((gpio_num_t)3, 0);
}
